/* harc előtti pillanatok: a Féregnek adható víz, Szilárdnál dől el a befejezés */
function preFight(e, go) { if (e.t === 'fereg' && P.f.viz) { choose('A Homokféreg', 'A homok megmozdul alattad. Nem támad – szimatol. A palackodat érzi.', [['Leteszem elé a tiszta vizet', () => { P.f.viz = 0; P.f.tojas = 1; e.st = 'dead'; e.tm = 0; P.dead.fereg = 1; P.sh.fereg = 1; cine([{ x: e.x, y: e.y - 30, T: 5, z: 1.25, cap: 'A Féreg megissza. Nem lesz tőle jobban – de megnyugszik. Elhever a mederben, és többé nem mozdul.' }, { x: e.x, y: e.y, T: 4.4, cap: 'Hálából hátrahagyja a szilánkot. És egy tojást.' }], () => { give('seed'); felled('SZÁRAZÚR ELSZENDERÜLT', `Forrásszilánk · ${DRY()} a nyolcból  ·  ${DRYN[DRY()]}`, 5.5); }); }], ['Megküzdök vele', go]]); return true; }
  if (e.t !== 'szil') return false; e.a = Math.atan2(P.y - e.y, P.x - e.x); if (P.thorn >= 3) { ending(4); return true; }
  const opts = [['Megküzdök vele', go]]; if (P.f.virag && P.f.csepp) opts.push(['Elültetem Kálmán virágát a Forrás Szívébe', () => ending(3)]); if (pages() >= 12 && P.f.kanna) opts.push(['Elmondom neki, amit a naplója mond', () => ending(5)]);
  const ask = () => opts.length > 1 ? choose('A Forrás Szíve', 'Szilárd a kiszáradt kútkáván ül, és vár.', opts) : go();
  if (!P.f.szI) { P.f.szI = 1; talk('Szikkadt Szilárd', ['Nyolc szilánkot hoztál. Nyolc darabot abból, amit én egyben tartottam.', 'Tudod, mit hoztál valójában? Nyolc darab halált. Minden szilánkkal, amit elvettél, valahol a világban kiszáradt egy kút.', 'Én őriztem azt, ami maradt. Te szétszórtad.', 'A kilencedik nem esett le, amikor ittam. Fölfelé ment. Láttam, ahogy a kút torkán át elszáll, mint egy csepp, ami nem akar hullani.'], ask); } else ask(); return true; }
/* ---------- befejezések ---------- */
const ENDS = { 1: ['A SZOMJAZÓ KORONÁJA', [['', 'Szilárd porrá omlik. A nyolc szilánk a kezedben lüktet. Nem hozod vissza a Forrást. Te iszod meg.'], ['', 'Erzsébet megérinti az arcodat, és sírni kezd. „Minden kútmester ugyanazt hiszi. Hogy ő majd másképp csinálja.”'], ['', 'A trónon ülsz, a kezedben egy kanna. A kút torkán át felnézel az égre. A harmadik nap visszanéz rád, és pislog.'], ['', '„Most már látsz minket, kútmester.”']]],
  2: ['A POHÁR', [['', 'Szilárd megáll. Észreveszi a kezedben Hanna poharát. Leteszed elé.'], ['', 'Elejti a kannáját, és két kézzel, remegve iszik. Nem lesz tőle jobban. A test már nem tud vizet tartani.'], ['', 'De a szeme kialszik, és utoljára emberként szól: „…Elkéstem vele. Három nappal.”'], ['', 'Elporlad. A Forrás nem tér vissza. De aznap éjjel Ázottföldön először esik harmat, magától.'], ['', 'Reggel a Harmatőrök lábnyomokat találnak a mezőn: mezítláb, könnyűek, a semmiből indulnak és a semmibe vesznek.']]],
  3: ['A KERTÉSZ', [['', 'Nem harcolsz. Elülteted Kálmán virágát a Forrás Szívébe, és megöntözöd Panni egyetlen cseppjével.'], ['', 'A virág kinyílik. Szilárd felismeri: ugyanaz, amit Rozáliának ültetett az esküvőjük napján. Leül mellé, és vár.'], ['', 'Évszázadokig. A kőből kibukkan egy apró ér. De a víz nem lefelé folyik: vékony, ezüst fonalban száll az égbe.'], ['', 'Szilárd kőalakja felnéz. „Ne engedd, hogy elvigyék… már másodszor…”'], ['', '„A víz nem a miénk. Mi csak az útja vagyunk.”']]],
  4: ['A KAKTUSZSZENT', [['', 'Mire a Mélybe érsz, már félig kaktusz vagy. Szilárd nem harcol veled: maga mellé ültet, a trónja alá.'], ['', 'Nem szomjazol többé. Nem érzel semmit. Mindenki boldog, mert senki nem emlékszik, milyen volt a víz.'], ['', 'Évszázadok telnek. Egy napon a kráter peremén megjelenik egy fehér köpenyes alak.'], ['', 'Megnézi a kaktuszokat, egy vödröt merít a kráter repedéséből, és elmegy. Te nem tudsz megmozdulni, hogy kövesd.']]],
  5: ['A MEGTÉRT', [['', 'Elmondod neki az igazat: a Forrás már a nagyapja idejében haldoklott. A Rend tudta. Nem ő ölte meg.'], ['', 'Szilárd nevet. Hosszan, szárazon, végül sírva.'], ['', 'Együtt mentek fel. Kannával a kézben járjátok a pusztát, és öntözitek a Kiszáradtakat. Vízzel nem, mert az nincs. Tisztelettel.'], ['', 'Északon eléritek a ködfalat. Megnyílik. Szilárd megáll: „Én ide nem mehetek be. Engem ott ismernek.”'], ['', 'Egyedül lépsz be. A kép elsötétül, és esőhang hallatszik. Először.']]] };
function ending(k) { bossOn = false; BOSS = null; BA = null; AOE = []; PRJ = []; P.fin = k; P.dead.szil = 1; save(); const E0 = ENDS[k], sh = E0[1].map((s, i) => ({ x: HEART[0] + (i % 2 ? 60 : -60), y: HEART[1] - 80 - i * 14, T: 7, z: 1.15 + i * .04, cap: s[1], dark: k === 5 && i === 4 ? 1 : 0 }));
  sh[0].title = E0[0]; sh.push({ x: HEART[0], y: HEART[1] - 170, T: 6, z: 1.4, cap: 'A Forrás Szíve tovább dobog. De a ritmusa megváltozott: kettős ütem, mintha két szív verne.' },
    { x: HEART[0], y: HEART[1] - 170, T: 7, dark: 1, cap: 'Egy fehér márványterem, a felhők fölött. Medencék, tele kristálytiszta vízzel. Kilenc fehér köpenyes alak ül egy asztal körül.' }, { x: HEART[0], y: HEART[1] - 170, T: 6, dark: 1, cap: '„Kútmester Szilárd elbukott. Ahogy terveztük.” – „És a Szomjazó?” – „Még él. Vagy legalábbis szomjas. Az elég.”' },
    { x: HEART[0], y: HEART[1] - 170, T: 6, dark: 1, cap: '„Akkor eresszétek le a következő cseppet.” Egy kéz kinyúl, és egy cseppet ejt egy kút szájába. Egy másik világ kútjába.' },
    { x: HUB[0], y: HUB[1], T: 8, cap: 'Az Utolsó Kút kávájába vésve: „Mindannyian kiszáradunk egyszer. A kérdés csak az, kinek adtuk oda az utolsó cseppünket. És ki gyűjtötte össze.”' });
  cine(sh, () => { P.x = HUB[0] - 50; P.y = HUB[1] + 60; P.fire = 2; P.hp = P.mhp; spawnAll(); CAM.x = P.x; CAM.y = P.y; REG = ''; save(); ST = 'end'; }); }
function drop(k, x, y, n) { const a = Math.random() * TAU, v = 60 + Math.random() * 120; PICK.push({ k, x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, t: 0, n }); }
function levelUp(i) { const k = STATS[i][0], c0 = statCost(k); if (P.gold < c0) return say('Nincs elég Harmatod.'); if (P[k] >= 99) return; P.gold -= c0; P[k]++; recalc(); P.hp = P.mhp; P.mp = P.mmp; R.st = P.mst; sfx(520, .5, 'triangle', .07, 500); FX.push({ k: 'ring', x: P.x, y: P.y, l: .7, r: 120, col: '255,211,90' }); save(); }
function forge() { const c0 = 150 * (P.wu + 1), o = P.wu >= 3 ? 2 : 1; if (P.wu >= 5) return; if (P.ore < o) return say('Nincs elég érckő.'); if (P.gold < c0) return say('Nincs elég Harmatod.'); P.ore -= o; P.gold -= c0; P.wu++; sfx(300, .12, 'square', .06, 500); hiss(.2, .08, 2000); banner('KÖNNYEL EDZVE', WEP[P.wep].n + ' +' + P.wu, 2.2); save(); }
function travel(i) { const f = FIRES[i]; if (!f || !P.fires[i]) return; P.fire = i; P.x = f[0] - 50; P.y = f[1] + 50; P.fz = 0; P.lx = null; FADE = 1; spawnAll(); PICK = []; CAM.x = P.x; CAM.y = P.y; REG = ''; ST = 'play'; save(); sfx(330, .6, 'sine', .06, 300); }
function summon(t, x, y) { const s2 = { t, x, y, hx: x, hy: y, hp: ET[t].hp, mhp: ET[t].hp, dm: 1, lv: 1, st: 'chase', tm: 0, a: 0, vx: 0, vy: 0, cd: 1, ph: Math.random() * 9, wt: 0, hurt: 0, n: 0, walk: 0, sum: 1, tx: x, ty: y }; EN.push(s2); FX.push({ k: 'ring', x, y, l: .6, r: 70, col: '125,240,255' }); return s2; }
